import React, { useState } from "react";

function SafetyCheck() {
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const checkSafety = async () => {
    try {
      setLoading(true);
      setMessage("");

      const res = await fetch('http://localhost:5000/api/safety/check', {

        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          latitude: 25.3176, // Varanasi example
          longitude: 82.9739,
        }),
      });

      const data = await res.json();

      if (data.risk && data.risk.inRisk) {
        setMessage("⚠️ You are in a risk zone!");
      } else {
        setMessage("✅ You are safe!");
      }
    } catch (error) {
      console.error("Error:", error);
      setMessage("❌ Error checking safety.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ textAlign: "center", marginTop: "100px" }}>
      <h2>Smart Tourist Safety Check</h2>
      <button
        onClick={checkSafety}
        disabled={loading}
        style={{
          background: "#007bff",
          color: "white",
          padding: "10px 20px",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
          fontSize: "16px",
        }}
      >
        {loading ? "Checking..." : "Check Safety"}
      </button>
      {message && (
        <p style={{ marginTop: "20px", fontSize: "18px" }}>
          {message}
        </p>
      )}
    </div>
  );
}

export default SafetyCheck;
